  ui_story_31730401_79_dialog_content = "Eu só estou dizendo isso uma vez, então ouça com atenção! Assim que eu terminar de falar, vamos pegar todo o contrabando aqui e seguir para o próximo ponto de encontro!",
  ui_story_31730401_80_dialog_content = "Eu tinha algumas roupas feitas sob medida para se parecerem com as usadas pelos servos da família Andersen. Usaremos isso como disfarce para entrar.",
