  ui_story_31730401_105_dialog_content = "Assim como eu previ, mais ou menos.",
  ui_story_31730401_106_dialog_content = "Nesse caso... acho que está na hora de acabar com esse joguinho.",
  ui_story_31730401_107_dialog_content = "Com um evento tão importante para assistir esta noite, eu realmente queria evitar sujar minhas mãos com o fedor de vermes...",
  ui_story_31730401_108_dialog_content = "Mas como os vermes costumam fugir, suponho que devo terminar isso rapidamente e lavar o fedor quando voltar.",
  ui_story_31730401_109_dialog_content = "Por outro lado, como um mordomo orgulhoso, sempre fico feliz em limpar as coisas.",
  ui_story_31730401_110_dialog_content = "Então, por favor, não tenha medo... Na verdade, sou muito gentil.",
  ui_story_31730401_111_dialog_content = "O primeiro passo para manter uma casa limpa e arrumada—",
  ui_story_31730401_112_dialog_content = "– é recolher todo o lixo e descartá-lo adequadamente.",
  ui_story_31730401_113_dialog_content = "Saudações, PlayerName, e bem-vindo novamente à casa do meu mestre.",
  ui_story_31730401_114_dialog_content = "Você descansou adequadamente em seu quarto? Os refrescos e dispositivos de entretenimento foram do seu agrado?",
  ui_story_31730401_115_option_content = "Com certeza!",
  ui_story_31730401_116_dialog_content = "Apenas a resposta que eu queria ouvir.",
  ui_story_31730401_117_dialog_content = "É, Minos...? Você está se sentindo bem? Você não parece muito bem...",
