  ui_story_31730401_122_dialog_content = "Minhas desculpas se minha aparência lhe causou preocupação.",
  ui_story_31730401_123_dialog_content = "Preocupar nossos estimados hóspedes é uma das piores coisas que um mordomo pode fazer.",
  ui_story_31730401_124_dialog_content = "Talvez eu deva usar alguns cosméticos femininos para iluminar minha aparência?",
