  ui_story_31730401_126_dialog_content = "Ah, eu só estou brincando.",
  ui_story_31730401_127_dialog_content = "Agora, Sr. Navegador, por favor, dirija-se ao salão de banquetes e desfrute da sua refeição.",
  ui_story_31730401_128_dialog_content = "Infelizmente, ainda tenho outros assuntos para tratar.",
  ui_story_31730401_129_dialog_content = "Antes que a festa comece a sério, devo fazer um relatório urgente ao meu mestre.",
