  ui_story_31730401_138_dialog_content = "É este o poder da antiga nobreza?",
  ui_story_31730401_139_dialog_content = "Parece que cada quarto de hóspedes foi abastecido com todos os tipos de refrescos e instalações de recreação... Se eu não soubesse melhor, eu diria que ainda estávamos em Lumopolis!",
  ui_story_31730401_140_dialog_content = "E com este pequeno anúncio fora do caminho, peço que aproveitem tudo o que nosso banquete oferece.",
  ui_story_31730401_141_dialog_content = "O que é que foi isso? Você ouviu isso agora mesmo?",
