  ui_story_31730401_148_dialog_content = "Sim, mestre.",
  ui_story_31730401_149_dialog_content = "Arranjei alguém para detonar os fogos de artifício. Miss Nina também é bastante insistente em vê-los.",
  ui_story_31730401_150_dialog_content = "Eu vejo. Muito bem, Minos.",
  ui_story_31730401_151_dialog_content = "Ah, e o vinho que você nos forneceu hoje é absolutamente requintado.",
  ui_story_31730401_152_dialog_content = "Que gracioso da sua parte dizer isso, Mestre... Mas tudo isso faz parte do meu dever como seu humilde mordomo.",
  ui_story_31730401_153_dialog_content = "Cuidado, senhorita Nina. Não fique muito tempo fora, para não pegar um resfriado!",
  ui_story_31730401_154_dialog_content = "Eu sei, eu sei!",
  ui_story_31730401_155_dialog_content = "Ah, e Minos?",
  ui_story_31730401_156_dialog_content = "Quando a casa assombrada estará pronta? Eu comprei todos os tipos de adereços para ele!",
  ui_story_31730401_157_dialog_content = "Em breve, Srta.",
  ui_story_31730401_158_dialog_content = "Confie em mim, quero dizer, muito em breve.",
  ui_story_31730601_2_dialog_content = "Não—!",
  ui_story_31730601_3_dialog_content = "Eu estive comprando aqui o tempo todo. Como poderia de repente... estar fechado...",
  ui_story_31730601_4_dialog_content = "Oh? Este não é o Sr. Navegador?",
  ui_story_31730601_5_dialog_content = "Ouvi um grito agora há pouco e vim verificar. Você está em algum tipo de problema?",
  ui_story_31730601_6_dialog_content = "Ah... Desculpe por perturbá-lo. Na verdade, não é grande coisa.",
  ui_story_31730601_7_dialog_content = "A loja onde eu sempre costumava comprar de repente fechou, deixando-me sem saber onde fazer compras agora.",
  ui_story_31730601_8_dialog_content = "Os negócios em Umbraton vêm e vão o tempo todo. Eles frequentemente têm que fechar por um motivo ou outro.",
  ui_story_31730601_9_dialog_content = "Portanto, é aconselhável que você não se inscreva para a associação, pois há uma grande chance de ser enganado.",
  ui_story_31730601_10_dialog_content = "... Não é como se eu tivesse dinheiro suficiente para me inscrever na associação.",
  ui_story_31730601_11_dialog_content = "O que você gostaria de comprar?",
  ui_story_31730601_12_dialog_content = "Hmm... Quero comprar papel de embrulho e fitas para me preparar para o feriado.",
  ui_story_31730601_13_dialog_content = "Oh? Nesse caso, eu conheço um lugar para você.",
  ui_story_31730601_14_dialog_content = "Por favor, permita-me mostrar o caminho para você.",
  ui_story_31730601_15_dialog_content = "Isso é muito gentil da sua parte. Você também acabou de fazer compras? Com todas essas bolsas aqui...",
  ui_story_31730601_16_dialog_content = "Certo, sim. Eu estive em várias lojas, tentando escolher os itens mais custo-efetivos.",
  ui_story_31730601_17_dialog_content = "Por favor, não se preocupe. Estamos realmente a caminho. O tempo tem estado úmido ultimamente, então preciso comprar algum incenso repelente de insetos.",
  ui_story_31730601_18_dialog_content = "Caso contrário... Tenho medo que você ache divertido. A mocinha pode fazer birra novamente.",
  ui_story_31730601_19_dialog_content = "Não, não... Deixe-me dar-lhe uma pequena ajuda!",
  ui_story_31730601_20_dialog_content = "Obrigado por sua gentileza então.",
  ui_story_31730601_21_dialog_content = "Uau, todas as mercadorias nas bolsas já foram realmente classificadas?",
  ui_story_31730601_22_dialog_content = "Você realmente cobre todas as bases como um mordomo.",
  ui_story_31730601_23_dialog_content = "É quase como se você tivesse nascido para ser um mordomo. Mal se parece...",
  ui_story_31730601_24_dialog_content = "Você quer dizer um assassino?",
  ui_story_31730601_25_dialog_content = "Ah, desculpe... Acho que me empolguei um pouco...",
  ui_story_31730601_26_dialog_content = "Sem problemas, alguém já disse isso sobre mim antes...",
  ui_story_31730601_27_dialog_content = "Ainda temos um longo caminho pela frente. Quer ouvir algumas histórias do meu passado?",
  ui_story_31730601_28_dialog_content = "Claro que não!",
  ui_story_31730601_29_dialog_content = "Pensando bem, foi ela quem salvou minha vida...",
  ui_story_31730601_30_dialog_content = "<color=#e8d9bb>Ka-thunk!!</color>",
  ui_story_31730601_31_dialog_content = "Humpf, que touro teimoso para domar...",
  ui_story_31730601_32_dialog_content = "Foi você quem eliminou oito dos meus caras?",
  ui_story_31730601_33_dialog_content = "Eu vim com um presente do mestre, e é assim que você retribui a gentileza dele...?",
  ui_story_31730601_34_dialog_content = "Que vergonhoso. Você deveria ter vergonha de se chamar aliado da família!",
  ui_story_31730601_35_dialog_content = "Bondade? Aliados? Não, se você mora aqui, deveria saber que não nos preocupamos com essas coisas.",
  ui_story_31730601_36_dialog_content = "O poder é tudo, não precisamos de uma família fraca.",
  ui_story_31730601_37_dialog_content = "Como ousa fazer um discurso tão ganancioso e sem vergonha?",
  ui_story_31730601_38_dialog_content = "Heh, vou mostrar pra todos vocês—",
  ui_story_31730601_39_dialog_content = "?!",
  ui_story_31730601_40_dialog_content = "Leve-o para baixo!",
  ui_story_31730601_41_dialog_content = "D-Não deixe ele se aproximar do chefe!",
  ui_story_31730601_42_dialog_content = "Traição e deslealdade... Essa é a verdadeira fraqueza!",
  ui_story_31730601_43_dialog_content = "... Quase.",
  ui_story_31730601_44_dialog_content = "Que tolo lamentável. Qualquer assassino sabe que a melhor maneira de se manter vivo é se juntar ao grupo mais forte.",
  ui_story_31730601_45_dialog_content = "Faça o que quiser, eu não me importo...",
  ui_story_31730601_46_dialog_content = "Eu não sou você... Eu nunca trairia o mestre e a mocinha.",
  ui_story_31730601_47_dialog_content = "Então, se eu te levasse para a negociação com os Andersen...",
  ui_story_31730601_48_dialog_content = ".. e mostre ao seu mestre o quão lamentável você se tornou?",
  ui_story_31730601_49_dialog_content = "Você—!",
  ui_story_31730601_50_dialog_content = "Cale-o, depois coloque-o no caso que ele trouxe.",
  ui_story_31730601_51_dialog_content = "Sim!",
  ui_story_31730601_52_dialog_content = "Já que os Andersens me deram um presente, eu deveria retribuir o gesto.",
  ui_story_31730601_53_dialog_content = "Fera! Eu deveria te matar... Eu deveria ter... Ai!!!",
  ui_story_31730601_54_dialog_content = "<color=#e8d9bb>Assim mesmo, fui colocado na mala e posto numa carruagem.</color>",
  ui_story_31730601_55_dialog_content = "<color=#e8d9bb>Eles estavam correndo, mas pararam. Talvez tenha havido uma colisão ou algo assim, ou outra gangue.</color>",
  ui_story_31730601_56_dialog_content = "<color=#e8d9bb>Eu luto para sair do vagão, mas não consigo abrir o estojo.</color>",
  ui_story_31730601_57_dialog_content = "<color=#e8d9bb>Então, senti mãos fracas darem um empurrão trêmulo na caixa em que eu estava...</color>",
  ui_story_31730601_58_dialog_content = "<color=#e8d9bb>Baque-</color>",
  ui_story_31730601_59_dialog_content = "...",
  ui_story_31730601_60_dialog_content = "Não é algum dinheiro sujo ou jóias da gangue...",
  ui_story_31730601_61_dialog_content = "Eu te decepcionei, não decepcionei?",
  ui_story_31730601_62_dialog_content = "...!",
  ui_story_31730601_63_dialog_content = "Achei que era apenas um gatinho ou cachorrinho, mas... mas...",
  ui_story_31730601_64_dialog_content = "O mundo é um tapete de eventos inesperados.",
  ui_story_31730601_65_dialog_content = "Se você não quer se meter em problemas, é melhor sair...",
  ui_story_31730601_66_dialog_content = "Eu... eu sei...",
  ui_story_31730601_67_dialog_content = "<color=#e8d9bb>Estrondo-</color>",
  ui_story_31730601_68_dialog_content = "...?!",
  ui_story_31730601_69_dialog_content = "O que você vai fazer... Por que ainda está me empurrando?!",
  ui_story_31730601_70_dialog_content = "Você estaria morto se eu te deixasse aqui, não estaria?",
  ui_story_31730601_71_dialog_content = "Eu conheço um hospital subterrâneo que se especializa em tratar pessoas como você.",
  ui_story_31730601_72_dialog_content = "Eu te levo lá, mas quanto ao que acontece depois... Eu realmente não saberia...",
  ui_story_31730601_73_dialog_content = "Sabendo quem eu sou, ainda quer me salvar?",
  ui_story_31730601_74_dialog_content = "E-Eu não gosto do cheiro de sangue em você...",
  ui_story_31730601_75_dialog_content = "Mas mesmo com um cheiro tão forte de sangue, ainda consigo sentir o aroma de farinha e manteiga em você.",
  ui_story_31730601_76_dialog_content = "Aqueles verdadeiros gangsters... Eles exalam o cheiro de cachimbos, bebidas baratas e cassinos.",
  ui_story_31730601_77_dialog_content = "Então você é como um cozinheiro ou um mordomo, um bom jovem que ficou preso nessa bagunça, certo?",
  ui_story_31730601_78_dialog_content = "Era uma senhora afiada.",
  ui_story_31730601_79_dialog_content = "E nessas circunstâncias... é realmente admirável.",
  ui_story_31730601_80_dialog_content = "Ah, chegamos. Este é o lugar.",
  ui_story_31730601_81_dialog_content = "Este é o seu amigo, jovem Sr. Butler?",
  ui_story_31730601_82_dialog_content = "Ele é um amigo próximo, e é a primeira vez que ele vem aqui, então você se importaria em nos dar um desconto?",
  ui_story_31730601_83_dialog_content = "Sem problema, claro... um amigo próximo do jovem Sr. Butler.",
  ui_story_31730601_84_dialog_content = "N-Prazer em conhecê-lo.",
  ui_story_31730601_85_dialog_content = "*Cheirando*",
  ui_story_31730601_86_dialog_content = "Huh... Eu, eu tenho um certo cheiro em mim?",
  ui_story_31730601_87_dialog_content = "Ah, desculpe, minha visão não é muito boa, então costumo lembrar dos clientes pelo cheiro.",
  ui_story_31730601_88_dialog_content = "Você... Você cheira como o céu.",
  ui_story_31730601_89_dialog_content = "É tão claro, brilhante e progressista. É um sopro de ar fresco.",
  ui_story_31730601_90_dialog_content = "Combina tão bem com o aroma amanteigado e farinhento do jovem Sr. Mordomo.",
  ui_story_31730601_91_dialog_content = "Você trabalha no Centro de Transporte?",
  ui_story_31730601_92_dialog_content = "Tenho buquês e aromaterapia adequados para dirigíveis. Gostaria de fazer uma compra?",
  ui_story_31730601_93_dialog_content = "Sim, por favor. Eu realmente preciso de alguns desses.",
  ui_story_31730601_94_dialog_content = "... Então essa é a senhora que te salvou?",
  ui_story_31730601_95_dialog_content = "Sim, afinal, foi um favor que salvou minha vida. Ela me ajudou a escapar e voltar para os Andersens.",
  ui_story_31730601_96_dialog_content = "Agora que ela está mais velha, costumo visitá-la com frequência.",
  ui_story_31730601_97_dialog_content = "E você me trouxe aqui...",
  ui_story_31730601_98_option_content = "Para que eu possa te entender melhor?",
  ui_story_31730601_99_dialog_content = "Ah, eu não esperava que você entendesse as coisas dessa maneira.",
  ui_story_31730601_100_dialog_content = "Mas de certa forma, sim. Meu passado está inextricavelmente ligado à história de derramamento de sangue da família.",
  ui_story_31730601_101_dialog_content = "E compartilhar com você algo que nunca contei a ninguém antes realmente me traz uma sensação de alívio.",
  ui_story_31730601_102_option_content = "Então, para que eu possa fazer companhia a ela também?",
  ui_story_31730601_103_dialog_content = "Claro, ela provavelmente ficaria ainda mais feliz com mais pessoas por perto.",
  ui_story_31730601_104_dialog_content = "E esta também é a primeira vez que levo alguém que sabe sobre este assunto para o lugar dela.",
  ui_story_31730601_105_dialog_content = "Você também chegou a conhecer um dos meus segredos.",
  ui_story_31730601_106_dialog_content = "Seria minha maior honra.",
  ui_story_31730601_107_dialog_content = "De qualquer forma, este é um lugar maravilhoso, sinta-se à vontade para fazer sua escolha aqui.",
  ui_story_31730601_108_dialog_content = "Obrigado, tenho certeza de que vou encontrar algo de que gosto aqui!"
}
return config
